// CommonJS
// math.js
const add = (a, b) => a + b;
module.exports = { add };

// app.js
const { add } = require('./math');
console.log(add(1, 2));

// ES Modules
// math.mjs
export const add = (a, b) => a + b;
export default function multiply(a, b) { return a * b; }

// app.mjs
import multiply, { add } from './math.mjs';
console.log(add(1, 2));

// CJS和ESM互操作
// 在CJS中使用ESM（Node 14+）
async function main() {
  const { add } = await import('./math.mjs'); // 动态import
}

